function audit=ReadC1WorkingCoreSetSnapshot_v3(ExportSpecs,maxWallSeconds,confirmedIdle)
%READC1WORKINGCORESETSNAPSHOT_V3 Explicit closed working-core summaries.
% One public native hydration per selected core validates its loading contract.
% Remaining rows use retained plain values, not reconstructed/admitted orbits.
% This local read-only clock is independent of expired continuation grants.
% Each spec has exactly manifest_reference, export_file and
% export_closure_reference. This path returns a summary without writing files.
    assert(nargin==3&&isequal(confirmedIdle,true)&&iscell(ExportSpecs)&&iscolumn(ExportSpecs)&&~isempty(ExportSpecs), ...
        'C1WorkingSnapshot:Selection','Use an explicit nonempty column of closed working-core selections.');
    validateattributes(maxWallSeconds,{'double'},{'real','finite','scalar','>',20,'<=',600});
    for k=1:numel(ExportSpecs),fields(ExportSpecs{k},{'manifest_reference';'export_file';'export_closure_reference'});end
    begin=clocks();finish=struct('utc',begin.utc+maxWallSeconds,'mono',begin.mono+maxWallSeconds*1e9);
    methods={methodReference('ReadC1WorkingCoreSetSnapshot_v3');methodReference('LoadC1WorkingSolutionCore29_v3'); ...
        methodReference('RoundSHA256_v3');methodReference('C1ScientificDigest_v3')};
    audit=struct('schema','C1-closed-working-core29-readonly-snapshot-v1','complete',false,'source_posthash',false, ...
        'local_cap_seconds',maxWallSeconds,'operation_finish',finish,'files',{cell(0,1)},'current_references',{{}}, ...
        'current_methods',{methods},'native_hydrations',0,'new_maps',0,'new_corrections',0,'new_replays',0, ...
        'new_classifications',0,'new_admissions',0,'source_currentness_claimed',false,'completed_branch_claimed',false, ...
        'output_files_written',false,'scope','Closed SHA-bound working snapshots only. All saved decisions and nonhydrated NativeIDs remain historical; no fresh qualification, current raw-source coverage or branch completion is inferred.');
    seen=cell(0,1);pins=cell(0,1);
    for f=1:numel(ExportSpecs)
        check(finish);spec=ExportSpecs{f};fields(spec,{'manifest_reference';'export_file';'export_closure_reference'});
        mr=checked(spec.manifest_reference);er=checked(spec.export_closure_reference);file=literal(spec.export_file);
        assert(~ismember(file,seen),'C1WorkingSnapshot:Duplicate','Select each complete working core once.');seen{end+1,1}=file;
        assert(endsWith(lower(mr.file),'.mat')&&endsWith(lower(er.file),'.json'), ...
            'C1WorkingSnapshot:Manifest','The working variant requires its native MAT manifest and external export closure JSON.');
        z=load('-mat',mr.file,'manifest','manifest_digest');m=z.manifest;
        assert(strcmp(C1ScientificDigest_v3(m),z.manifest_digest) ...
            &&m.completed&&m.source_posthash&&isempty(fieldnames(m.pending_call))&&~m.scientific_completion_claimed, ...
            'C1WorkingSnapshot:Manifest','Require an intact completed manifest with no pending writer call.');clear z
        switch m.schema
            case 'PK30h-final-eligible-working-core-set-v1'
                exportClosureSchema='PK30h-final-working-core-set-external-closure-v1';
                graphClosureSchema='PK30h-eligible-stored-graph-external-closure-v1';
            case 'PK15h-final-current-working-core-set-v1'
                exportClosureSchema='PK15h-final-current-working-core-set-external-closure-v1';
                graphClosureSchema='PK15h-current-component-view-external-closure-v1';
            otherwise
                error('C1WorkingSnapshot:Manifest','Unsupported completed working-core manifest schema.');
        end
        closed=jsondecode(fileread(er.file));
        assert(strcmp(closed.schema,exportClosureSchema) ...
            &&sameReference(closed.manifest_reference,mr)&&sameReference(closed.graph_reference,m.plan_reference) ...
            &&sameReference(closed.graph_external_closure_reference,m.graph_external_closure_reference) ...
            &&closed.process.actual_tool_exit_observed&&closed.process.exit_code==0 ...
            &&closed.independent_post_guard.all_passed&&closed.all_owned_native_workers_closed, ...
            'C1WorkingSnapshot:ExportClosure','Require actual exporter exit, independent postguards and exact manifest/graph joins.');
        gr=checked(m.plan_reference);gc=checked(m.graph_external_closure_reference);gclosed=jsondecode(fileread(gc.file));
        assert(strcmp(gclosed.schema,graphClosureSchema) ...
            &&sameReference(gclosed.graph_reference,gr)&&gclosed.process.actual_tool_exit_observed ...
            &&gclosed.process.exit_code==0&&gclosed.independent_post_guard.all_passed, ...
            'C1WorkingSnapshot:GraphClosure','The exact stored graph requires its actual closed observation.');
        rows=m.core_rows;assert(iscell(rows)&&numel(rows)==m.component_count,'C1WorkingSnapshot:Rows');
        hit=find(cellfun(@(r)strcmp(r.core_reference.file,file),rows));assert(isscalar(hit),'C1WorkingSnapshot:CoreSelection');row=rows{hit};cr=checked(row.core_reference);
        named=asCells(closed.core_references);assert(sum(cellfun(@(r)sameReference(r,cr),named))==1 ...
            &&row.actual_helper_returned&&row.reader_completed&&row.actual_returned_receipt.completed ...
            &&row.actual_returned_receipt.source_posthash&&row.actual_returned_receipt.installed_native_read2 ...
            &&row.actual_returned_receipt.all_native_ids_and_policies_verified, ...
            'C1WorkingSnapshot:CoreClosure','Bind one actually returned whole-component export and its independent closure.');
        [sample,report,point,view]=LoadC1WorkingSolutionCore29_v3(cr.file,1,cr.sha256);audit.native_hydrations=audit.native_hydrations+1;
        z=load('-mat',cr.file,'solution_core29','core_digest');c=z.solution_core29;
        assert(strcmp(C1ScientificDigest_v3(c),z.core_digest)&&c.point_count==row.point_count ...
            &&numel(row.global_indices)==c.point_count&&sameReference(c.source_reference,gr) ...
            &&sameReference(view.source_reference,gr)&&view.external_binding_checked ...
            &&strcmp(point.native_id,c.native_ids{1})&&point.requires_fresh_replay&&~point.fresh_admission_claimed ...
            &&report.core29_view.saved_decisions_are_historical&&isempty(sample.trajectory), ...
            'C1WorkingSnapshot:CoreBinding','Keep exact complete payload and the one public historical native reconstruction.');
        equal(view.solution_matrix,c.solution_matrix);equal(view.native_energy,c.native_energy);equal(view.signed_mean_U,c.signed_mean_U);
        equal(view.point_metadata,c.point_metadata);equal(view.native_ids,c.native_ids);equal(view.typed_graph,c.graph);
        equal([sample.initial_state;sample.stride_displacement;sample.period],c.solution_matrix(:,1));
        points=cell(c.point_count,1);reports=points;
        for k=1:c.point_count
            check(finish);context=c.contexts{k};metadata=c.point_metadata{k};r=c.saved_reports{k};[present,allNine]=nine(r);
            assert(context.expected_index==k&&context.source_index==row.global_indices(k)&&sameReference(context.source_reference,gr), ...
                'C1WorkingSnapshot:Occurrence','Every local occurrence retains its exact original graph selector.');
            points{k}=struct('point_index',k,'global_index',context.source_index,'component_identity',metadata.component_identity, ...
                'order',metadata.order,'native_id',c.native_ids{k},'occurrence_id',context.occurrence_id,'role',context.role, ...
                'initial_state',c.solution_matrix(1:14,k),'T',c.solution_matrix(29,k),'full_stride',c.solution_matrix(15:28,k), ...
                'E',c.native_energy(k),'signed_apex_dx',c.solution_matrix(2,k),'signed_mean_U',c.signed_mean_U(k), ...
                'accepted_present',isfield(r,'accepted'),'accepted',get(r,'accepted',[]),'all_nine_present',present, ...
                'all_nine_true',allNine,'classification',pick(get(r,'classification',struct()), ...
                {'contract_version','validated_gait_type','canonical_point_label','canonical_label_qualified','flight_count_certain','flight_count'}), ...
                'native_reconstruction_performed',k==1,'saved_decisions_are_historical',true);
            reports{k}=struct('point_index',k,'native_id',c.native_ids{k},'point_metadata',metadata,'all_nine_present',present, ...
                'all_nine_true',allNine,'report',pick(r,{'status','native_status','accepted','acceptance_gates','family_conditions', ...
                'full_closure','within_original_clock','failure_stage','primary_failure'}),'classification',points{k}.classification, ...
                'saved_solver_present',isfield(r,'solver'),'native_reconstruction_performed',k==1,'saved_decisions_are_historical',true);
        end
        targets=asCells(m.representative_current_P_terminal_heads);heads=targets(cellfun(@(h)ismember(h.global_index,row.global_indices),targets));
        for k=1:numel(heads),at=find(row.global_indices==heads{k}.global_index);assert(isscalar(at)&&strcmp(heads{k}.native_ID,c.native_ids{at}),'C1WorkingSnapshot:HeadID');heads{k}.local_index=at;end
        one=struct('source',cr,'manifest_reference',mr,'export_closure_reference',er,'source_reference',gr, ...
            'indexed_point_count',c.point_count,'typed_graph',view.typed_graph,'points',{points},'report_views',{reports}, ...
            'representative_current_P_terminal_heads',{heads},'ranges',ranges(view),'working_storage',view.working_storage, ...
            'public_native_sample_index',1,'nonhydrated_ids_are_retained_historical',true,'source_unchanged',true, ...
            'source_currentness_claimed',false,'completed_branch_claimed',false);
        pins=[pins;{mr;er;gr;gc;cr}];verify(pins);verify(methods);check(finish);audit.files{end+1,1}=one;clear c z sample report point view points reports
    end
    verify(pins);verify(methods);check(finish);audit.complete=true;audit.source_posthash=true;audit.current_references=pins;
end
function out=ranges(v)
    out=struct('E',[min(v.native_energy),max(v.native_energy)],'signed_apex_dx',[min(v.solution_matrix(2,:)),max(v.solution_matrix(2,:))], ...
        'signed_mean_U',[min(v.signed_mean_U),max(v.signed_mean_U)],'T',[min(v.solution_matrix(29,:)),max(v.solution_matrix(29,:))]);
end
function [present,yes]=nine(r)
    names={'full_closure','mode_closure','target_energy','trajectory_energy_variation','unscaled_family_equations','family_constraint','physical_inequalities','primitive_identity','replay_determinism'};
    g=get(r,'acceptance_gates',struct());present=isstruct(g)&&isscalar(g)&&all(isfield(g,names));yes=present&&all(cellfun(@(n)isequal(g.(n),true),names));
end
function r=methodReference(name),file=which(name);assert(~isempty(file),'C1WorkingSnapshot:Provider');r=checked(struct('file',file,'sha256',RoundSHA256_v3(file)));end
function r=checked(r)
    assert(isstruct(r)&&isscalar(r)&&all(isfield(r,{'file','sha256'}))&&all(ismember(fieldnames(r),{'file';'sha256';'bytes';'name'})), ...
        'C1WorkingSnapshot:Reference');r.file=literal(r.file);assert(ischar(r.sha256)&&isrow(r.sha256)&&~isempty(regexp(r.sha256,'^[0-9a-f]{64}$','once')),'C1WorkingSnapshot:SHA');
    d=dir(r.file);assert(isscalar(d)&&~d.isdir&&strcmp(RoundSHA256_v3(r.file),r.sha256),'C1WorkingSnapshot:Changed');
    if isfield(r,'bytes'),assert(d.bytes==r.bytes,'C1WorkingSnapshot:Bytes');else,r.bytes=d.bytes;end
end
function verify(refs),for k=1:numel(refs),checked(refs{k});end,end
function yes=sameReference(a,b),yes=isstruct(a)&&isstruct(b)&&all(isfield(a,{'file','sha256'}))&&all(isfield(b,{'file','sha256'}))&&strcmp(a.file,b.file)&&strcmp(a.sha256,b.sha256);end
function fields(s,n),assert(isstruct(s)&&isscalar(s)&&isequal(sort(fieldnames(s)),sort(n(:))),'C1WorkingSnapshot:MixedSpecs','Do not mix legacy exports with explicit native working-core specifications.');end
function c=asCells(v),if iscell(v),c=v(:);elseif isstruct(v),c=num2cell(v(:));else,error('C1WorkingSnapshot:Rows','Use literal saved row collections.');end,end
function o=pick(s,n),assert(isstruct(s)&&isscalar(s),'C1WorkingSnapshot:PlainReport');o=struct();for k=1:numel(n),if isfield(s,n{k}),o.(n{k})=s.(n{k});end,end,end
function v=get(s,n,d),v=d;if isstruct(s)&&isscalar(s)&&isfield(s,n),v=s.(n);end,end
function equal(a,b),assert(strcmp(C1ScientificDigest_v3(a),C1ScientificDigest_v3(b)),'C1WorkingSnapshot:TypedEquality');end
function p=literal(p),assert(ischar(p)&&isrow(p)&&~isempty(p),'C1WorkingSnapshot:Path');q=char(java.io.File(p).getCanonicalPath());assert(strcmp(p,q),'C1WorkingSnapshot:Path','Select the literal canonical snapshot path.');end
function t=clocks(),t=struct('utc',posixtime(datetime('now','TimeZone','UTC')),'mono',double(java.lang.System.nanoTime()));end
function check(limit),t=clocks();assert(t.utc<limit.utc&&t.mono<limit.mono,'C1WorkingSnapshot:LocalClock','The bounded read-only snapshot clock expired.');end
